const cfg = $json || {};
if (!cfg.locationId) throw new Error('Missing locationId');
if (!cfg.apiKey) throw new Error('Missing apiKey');

const baseUrl = String(cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const dryRun = cfg.dryRun !== undefined ? !!cfg.dryRun : true;

const headers = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

async function apiRequest(method, path, body) {
  const options = { method, url: `${baseUrl}${path}`, headers, json: true };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
      requestBody: body,
    };
  }
}

function getFieldsArray(obj) {
  if (Array.isArray(obj)) return obj;
  if (Array.isArray(obj?.customFields)) return obj.customFields;
  if (Array.isArray(obj?.data?.customFields)) return obj.data.customFields;
  if (Array.isArray(obj?.data)) return obj.data;
  return [];
}

function fieldName(f) { return f?.name || f?.label || f?.fieldName || ''; }
function normType(t) {
  const v = String(t || '').toUpperCase();
  if (['NUMERICAL','NUMERIC','NUMBER'].includes(v)) return 'NUMBER';
  if (v === 'DATE') return 'DATE';
  if (['DATE_TIME','DATETIME'].includes(v)) return 'DATETIME';
  return 'TEXT';
}

const requiredFields = [
  ['Apollo Contact Id','TEXT'],['Apollo Account Id','TEXT'],['Apollo Email Status','TEXT'],
  ['Apollo Primary Email Source','TEXT'],['Apollo Primary Email Verification Source','TEXT'],
  ['Apollo Email Confidence','NUMBER'],['Apollo Primary Email Catch-all Status','TEXT'],
  ['Apollo Primary Email Last Verified At','DATE'],['Apollo Seniority','TEXT'],['Apollo Departments','TEXT'],
  ['Apollo Sub Departments','TEXT'],['Apollo Company Employees','NUMBER'],['Apollo Industry','TEXT'],
  ['Apollo Keywords','TEXT'],['Apollo Person LinkedIn URL','TEXT'],['Apollo Company LinkedIn URL','TEXT'],
  ['Apollo Facebook URL','TEXT'],['Apollo Twitter URL','TEXT'],['Apollo Technologies','TEXT'],
  ['Apollo Annual Revenue','NUMBER'],['Apollo Total Funding','NUMBER'],['Apollo Latest Funding','TEXT'],
  ['Apollo Latest Funding Amount','NUMBER'],['Apollo Last Raised At','DATE'],['Apollo Subsidiary Of','TEXT'],
  ['Apollo Secondary Email','TEXT'],['Apollo Secondary Email Source','TEXT'],['Apollo Secondary Email Status','TEXT'],
  ['Apollo Secondary Email Verification Source','TEXT'],['Apollo Tertiary Email','TEXT'],
  ['Apollo Tertiary Email Source','TEXT'],['Apollo Tertiary Email Status','TEXT'],
  ['Apollo Tertiary Email Verification Source','TEXT'],['Apollo Primary Intent Topic','TEXT'],
  ['Apollo Primary Intent Score','NUMBER'],['Apollo Secondary Intent Topic','TEXT'],
  ['Apollo Secondary Intent Score','NUMBER'],['Apollo Qualify Contact','TEXT'],
].map(([name, requiredType]) => ({ name, requiredType }));

const res = await apiRequest.call(this, 'GET', `/locations/${cfg.locationId}/customFields?model=contact`);
if (!res.ok) throw new Error(`Failed to fetch custom fields: ${res.status} ${JSON.stringify(res.data)}`);

const existing = getFieldsArray(res.data);
const byName = new Map(existing.map((f) => [fieldName(f), f]).filter(([n]) => !!n));

const report = [];
const toCreate = [];
const conflicts = [];
for (const req of requiredFields) {
  const cur = byName.get(req.name);
  if (!cur) { toCreate.push(req); continue; }
  const curType = normType(cur?.dataType || cur?.fieldType || cur?.type || cur?.valueType);
  if (curType !== req.requiredType) {
    conflicts.push({ fieldName: req.name, existingType: cur?.dataType || cur?.fieldType || cur?.type || 'UNKNOWN', requiredType: req.requiredType });
  } else {
    report.push({ fieldName: req.name, fieldId: cur.id || cur._id || 'N/A', type: req.requiredType, action: 'Reused', group: 'Apollo Enrichment' });
  }
}

if (conflicts.length) return [{ json: { dryRun, locationId: cfg.locationId, targetGroupName: 'Apollo Enrichment', CONFLICT: conflicts } }];

async function createField(req) {
  const types = req.requiredType === 'NUMBER' ? ['NUMERICAL','NUMERIC'] : req.requiredType === 'DATE' ? ['DATE'] : req.requiredType === 'DATETIME' ? ['DATE_TIME','DATETIME'] : ['TEXT','LARGE_TEXT'];
  let lastError = null;
  for (const dataType of types) {
    const bodies = [
      { name: req.name, model: 'contact', dataType },
      { name: req.name, objectKey: 'contact', dataType },
    ];
    for (const body of bodies) {
      const out = await apiRequest.call(this, 'POST', `/locations/${cfg.locationId}/customFields`, body);
      if (out.ok) return out.data;
      lastError = out;
    }
  }
  throw new Error(`Failed creating field ${req.name}: ${JSON.stringify({ status: lastError?.status, data: lastError?.data, body: lastError?.requestBody })}`);
}

if (dryRun) {
  for (const req of toCreate) report.push({ fieldName: req.name, fieldId: 'N/A', type: req.requiredType, action: 'Planned Create (dryRun)', group: 'Apollo Enrichment' });
} else {
  for (const req of toCreate) {
    const created = await createField.call(this, req);
    report.push({ fieldName: req.name, fieldId: created?.id || created?.data?.id || created?.customField?.id || 'N/A', type: req.requiredType, action: 'Created', group: 'Apollo Enrichment' });
  }
}

report.sort((a,b)=>a.fieldName.localeCompare(b.fieldName));
return [{ json: { dryRun, locationId: cfg.locationId, targetGroupName: 'Apollo Enrichment', CUSTOM_FIELDS: report } }];
